module Ranvier.Anime.Tests.Program

open Expecto

let private referenceFile (name:string) =
    let root=System.Environment.GetEnvironmentVariable "RANVIER_ANIME_REFERENCE_ROOT"
    let root=if System.String.IsNullOrWhiteSpace root then System.IO.Path.Combine(System.AppContext.BaseDirectory,"reference") else root
    System.IO.Path.Combine(root,name)

[<EntryPoint>]
let main args = runTestsWithCLIArgs [] args (testList "native Anime" [RunnerTests.tests; ReactiveTests.tests; CssTests.tests; EaseTests.tests; CurveTests.tests; ValueInterpolationTests.tests; KeyframeCompilationTests.compilationTests; FrameSiblingTests.tests; KeyframePlaybackTests.playbackTests; KeyframePlaybackTests.interruptionTests; OwnedKeyframeChildTests.tests; KeyframeNumericTests.inputTests; KeyframeNumericTests.contractTests; RelativeKeyframeTests.tests; KeyframeComputedTests.sourceTests; KeyframeComputedTests.contractTests; KeyframeCssTests.cssSourceTests; KeyframeCssTests.cssContractTests; KeyframeSequenceTests.normalizationTests; KeyframeSequenceTests.playbackTests; KeyframeSequenceInputTests.tests; KeyframeSequenceContractTests.tests; CssSnapshotTests.tests; AnimatableValueTests.tests; AnimatableTrackTests.trackTests; AnimatableTrackTests.groupTests; AnimatableNumberTests.numericFacadeTests; AnimatableCssTests.cssFacadeTests; DeclarationTests.tests; UnitConversionTests.tests; SpringTests.tests; StaggerTests.tests; TimelineTests.tests; PlaybackTimingTests.tests; PlaybackStateTests.tests; TimerTests.tests; AnimationPlaybackTests.tests; TimelineClockTests.tests; TimelinePlaybackTests.tests; TimelineKeyframeTests.borrowedContractTests; TimelineOwnedFactoryTests.tests; TimelineNumericKeyframeTests.tests; TimelineCssKeyframeTests.tests; TimelineCssSequenceTests.tests; TimelineCssSequenceSourceTests.sourceTests; TimelineSequenceContractTests.tests; TimelineNumericKeyframeSourceTests.sourceTests; TimelineMixedKeyframeSourceTests.sourceTests; TimelineMixedContractTests.tests; TimelineRevertTests.restorationTests; ScopeTests.scopeLifecycleTests; ScopeReferenceTests.scopeReferenceTests; ScopeTimerReferenceTests.scopeTimerTests; ScopeResourceHookTests.scopeResourceTests; NumericScopeTests.numericScopeTests; ScopeFacadeClockTests.facadeClockTests; NumericCompleteFaultTests.numericCompleteFaultTests; ScopeAutomaticTests.automaticTests; CssScopeRestorationTests.cssScop